Method.Source:
    Query buildQuery()
    {
        Query                   q = new Query();
        QueryBuildDataSource    qb_tranCommittedCost;
        QueryBuildRange         metCommittedCostOrig;

        next buildQuery();
        qb_tranCommittedCost =  q.addDataSource(tableNum(CostControlTransCommittedCost));
        metCommittedCostOrig =  qb_tranCommittedCost.addRange(fieldnum(CostControlTransCommittedCost, CommittedCostOrig));


        if(this.args().menuItemName() == "METCostControlCommittedCost")
        {
           
            metCommittedCostOrig.value(strFmt('%1,%2',queryValue(CommittedCostOrig::PurchaseOrder),queryValue(CommittedCostOrig::PurchaseRequisition)));
        }

        return q;
    }
